var t=`0677-sauce-graine`;var i=`world-0677`;var a=`CI`;var s=`western-africa`;var o=4;var r=81;var l={en:`Sauce Graine`,ua:`Соус із пальмових горіхів`};var g={en:`Sauce Graine is a Côte d'Ivoire classic prepared with beef chuck, yellow onion, palm nut concentrate, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Соус із пальмових горіхів, страва кухні країни Кот-д'Івуар зі складниками: яловича лопатка, жовта цибуля, концентрат пальмових плодів, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var c=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,650,`g`],[`palm-oil`,35,`ml`],[`yellow-onion`,160,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`palm-nut-concentrate`,250,`g`],[`water`,880,`ml`],[`tomato`,230,`g`],[`okra`,170,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`spinach`,140,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:t,id:i,country:`CI`,region:s,servings:4,minutes:81,title:l,text:g,steps:c};export{a as country,u as default,i as id,r as minutes,s as region,o as servings,t as slug,c as steps,g as text,l as title};